.inspection-result__chevron {
  flex: none;
  color: color-mix(in oklab, var(--foreground) 62%, transparent);
  transition: transform 120ms ease;
}

.inspection-result__chevron[data-open="true"] {
  transform: rotate(180deg);
}

.inspection-result__panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 0 10px 10px;
}

.inspection-result__panel[hidden] {
  display: none;
}

.inspection-result__detail {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 2px 12px;
  margin: 0;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--background);
  font-size: 0.8125rem;
}

.inspection-result__detail dt {
  color: color-mix(in oklab, var(--foreground) 64%, transparent);
}

.inspection-result__detail dd {
  margin: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  overflow-wrap: anywhere;
}

.inspection-result__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.inspection-result__copy {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--background);
  color: inherit;
  font: inherit;
  font-size: 0.75rem;
  cursor: pointer;
}

.inspection-result__copy:hover {
  background: var(--muted);
}

.inspection-result__copy:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.inspection-result__feedback {
  font-size: 0.75rem;
  color: color-mix(in oklab, var(--foreground) 70%, transparent);
}
"}]}

